[asy]
size(7cm);
pair A=(0,0), B=(65,0), C=(117/5,156/5), D=(125/13,300/13), E=(23.4,0), F=(9.615,0);
draw(A--B--C--D--cycle);
draw(A--C);
draw(B--D);
